package com.hbm.satellite;
import com.mojang.brigadier.arguments.IntegerArgumentType;import net.minecraft.commands.Commands;import net.minecraft.network.chat.Component;import net.minecraft.ChatFormatting;import net.minecraft.server.level.ServerPlayer;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.RegisterCommandsEvent;
/** Actual original ntmsatellites administration command; not a substitute for the pending physical rocket launchers. */
@EventBusSubscriber(modid="hbm") public final class SatelliteCommands {
 @SubscribeEvent public static void register(RegisterCommandsEvent event){event.getDispatcher().register(Commands.literal("ntmsatellites").requires(source->source.hasPermission(2)).then(Commands.literal("orbit").executes(context->{var source=context.getSource();if(!(source.getEntity() instanceof ServerPlayer player)){source.sendFailure(Component.translatable("commands.satellite.should_be_run_as_player"));return 0;}var stack=player.getMainHandItem();if(!(stack.getItem() instanceof SatelliteFrequency)||stack.getItem()==SatelliteContent.CHIP.get()||!SatelliteRegistry.orbit(player.serverLevel(),stack,SatelliteFrequency.getFreqS(stack),player.getX(),player.getY(),player.getZ())){source.sendFailure(Component.translatable("commands.satellite.not_a_satellite"));return 0;}stack.shrink(1);source.sendSuccess(()->Component.translatable("commands.satellite.satellite_orbited").withStyle(ChatFormatting.GREEN),false);return 1;})).then(Commands.literal("descend").then(Commands.argument("frequency",IntegerArgumentType.integer()).suggests((context,builder)->{for(int freq:SatelliteSavedData.getData(context.getSource().getLevel()).frequencies())builder.suggest(freq);return builder.buildFuture();}).executes(context->{var source=context.getSource();if(!(source.getEntity() instanceof ServerPlayer)){source.sendFailure(Component.translatable("commands.satellite.should_be_run_as_player"));return 0;}boolean removed=SatelliteSavedData.getData(source.getLevel()).remove(IntegerArgumentType.getInteger(context,"frequency"));if(removed)source.sendSuccess(()->Component.translatable("commands.satellite.satellite_descended").withStyle(ChatFormatting.GREEN),false);else source.sendFailure(Component.translatable("commands.satellite.no_satellite"));return removed?1:0;}))).then(Commands.literal("list").executes(context->{var source=context.getSource();if(!(source.getEntity() instanceof ServerPlayer)){source.sendFailure(Component.translatable("commands.satellite.should_be_run_as_player"));return 0;}var data=SatelliteSavedData.getData(source.getLevel());if(data.sats.isEmpty()){source.sendFailure(Component.translatable("commands.satellite.no_active_satellites"));return 0;}data.sats.forEach((frequency,satellite)->source.sendSuccess(()->Component.literal(frequency+" - "+satellite.getClass().getSimpleName()).withStyle(ChatFormatting.GREEN),false));return data.sats.size();})));}
 private SatelliteCommands(){}
}
